-- 0095c (pedido 050): revisão 1.0 do fluxo (33 etapas, 10 papéis do processo) e leitura da tela.

-- revisão 1.0: as 33 etapas do mapa validado em 26/11/2026
create or replace function crm._fluxo_semear(p_empresa uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from crm.cad_fluxo_etapa where empresa_id = p_empresa) then return; end if;
  perform crm._fluxo_carregar(p_empresa, $semente${"funcoes": [{"codigo": "comprador", "nome": "Comprador", "descricao": "Negocia com fornecedores, importa a NF-e, fecha custo e preço e confirma a entrada.", "ordem": 1}, {"codigo": "conferente", "nome": "Conferente", "descricao": "Confere o que entra e o que sai: volumes, contagem, etiquetas, local e separação dos envios.", "ordem": 2}, {"codigo": "cadastro", "nome": "Cadastro", "descricao": "Transforma a nota em peças: desmembra grades, classifica grupo, marca e características.", "ordem": 3}, {"codigo": "marketing", "nome": "Marketing", "descricao": "Fotos, vídeo, conteúdo da oferta, publicação nos canais e vitrine.", "ordem": 4}, {"codigo": "apresentadora", "nome": "Apresentadora", "descricao": "Conduz a live, apresenta as peças pelo número curto e aprova conteúdo.", "ordem": 5}, {"codigo": "suporte", "nome": "Suporte de vendas", "descricao": "Fila, reservas, links de pagamento, Caixa de entrada, follow-up e pós-venda.", "ordem": 6}, {"codigo": "faturista", "nome": "Faturista", "descricao": "Garante o cadastro fiscal do parceiro, emite a NF-e de venda no Bling e trata as notas de devolução.", "ordem": 7}, {"codigo": "expedicao", "nome": "Expedição", "descricao": "Monta os envios por cliente, cobra o frete, posta e informa o rastreio.", "ordem": 8}, {"codigo": "financeiro", "nome": "Financeiro", "descricao": "Contas a pagar e a receber, baixas, conciliação bancária e taxas.", "ordem": 9}, {"codigo": "gestor", "nome": "Gestor", "descricao": "Define regras e preços, agenda as lives e fecha o mês no Painel de Gestão.", "ordem": 10}], "etapas": [{"codigo": "E01", "ordem": 1, "fase": 1, "area": "compras", "titulo": "Negociar e comprar com o fornecedor", "responsavel": "comprador", "apoio": ["gestor"], "tela": "Fora do painel (fornecedor). Consulta: Painel de Gestão e histórico de demanda perdida", "entrada": "Necessidade de reposição, vendas por grupo e peças que faltaram nas lives", "procedimento": ["Consultar no Painel de Gestão o que vendeu por grupo e canal e a demanda perdida por falta de estoque.", "Negociar preço, prazo de pagamento e frete (por conta do emitente ou do destinatário).", "Pedir ao fornecedor a NF-e com tamanho e cor na descrição de cada item.", "Registrar as condições combinadas para conferir na chegada."], "entrega": "Pedido ao fornecedor e, depois, a NF-e e o XML", "impacto": "Nota genérica (sem tamanho nem cor) multiplica o trabalho de desmembramento. Frete por conta do destinatário que não é anotado some do custo.", "regras": "Combinar sempre a forma de pagamento: nota sem parcelas exige lançar os vencimentos à mão.", "situacao": "man"}, {"codigo": "E02", "ordem": 2, "fase": 1, "area": "estoque", "titulo": "Receber a mercadoria e contar as peças", "responsavel": "conferente", "apoio": ["comprador"], "tela": "DANFE em mãos; depois Compras e estoque › Entrada de mercadoria", "entrada": "Chegada dos volumes com o DANFE", "procedimento": ["Conferir volumes e transportadora contra o DANFE.", "Contar as peças de cada linha da nota.", "Separar avarias e anotar divergências de quantidade.", "Guardar o comprovante do frete pago à transportadora (CT-e ou recibo).", "Entregar a contagem ao comprador."], "entrega": "Contagem física conferida", "impacto": "Divergência não anotada vira estoque fantasma e custo errado; a peça \"existe\" no painel e não na arara.", "regras": "Não confirmar a entrada antes da contagem física.", "situacao": "man"}, {"codigo": "E03", "ordem": 3, "fase": 1, "area": "compras", "titulo": "Importar o XML da NF-e", "responsavel": "comprador", "apoio": ["cadastro"], "tela": "Compras e estoque › Entrada de mercadoria › Importar XML", "entrada": "XML da nota de compra", "procedimento": ["Clicar em \"Importar XML\" e conferir o resumo e o fornecedor.", "Se o fornecedor não existir, cadastrar com o CNPJ da nota; os dados (IE, telefone, endereço pelo CEP) vêm do XML.", "Ler os avisos: frete do destinatário sem valor, transportadora \"O PROPRIO\", Simples sem crédito de ICMS, nota com mais de 90 dias, pagamento sem parcelas.", "Conferir a contagem do conferente contra as linhas importadas."], "entrega": "Entrada aberta com itens e sugestões de cadastro", "impacto": "Nota com mais de 90 dias pode já ter dado entrada: confirmar antes de seguir para não duplicar estoque e conta a pagar.", "regras": "Avisos informam, não bloqueiam. A confirmação final exige fornecedor vinculado.", "situacao": "uso"}, {"codigo": "E04", "ordem": 4, "fase": 2, "area": "cadastro", "titulo": "Desmembrar itens sem tamanho e cor", "responsavel": "cadastro", "apoio": ["conferente"], "tela": "Entrada de mercadoria › Itens sem tamanho › Desmembrar", "entrada": "Linhas genéricas da nota (ex.: 22 blusas sem grade)", "procedimento": ["Abrir \"Desmembrar\" na linha.", "Incluir um produto por modelo ou cor e escolher o tipo de grade.", "Informar a quantidade por tamanho até o contador fechar com a linha.", "Usar \"Repartir o que falta igualmente\" e \"Duplicar\" para ganhar tempo; ajustar à mão.", "Fazer isso antes de revisar as demais peças."], "entrega": "Itens com modelo, cor e tamanho; valor da linha repartido", "impacto": "Sem desmembrar a peça não ganha grade, etiqueta nem fila na live.", "regras": "O desmembramento só salva quando a soma fecha com a quantidade da linha.", "situacao": "uso"}, {"codigo": "E05", "ordem": 5, "fase": 2, "area": "cadastro", "titulo": "Cadastrar peças: grupo, marca, características e grade", "responsavel": "cadastro", "apoio": ["comprador"], "tela": "Entrada › Peças; Grupos de produto; Grades e atributos", "entrada": "Itens importados ou desmembrados", "procedimento": ["Usar \"Sugerir cadastro\" e revisar cada peça.", "Corrigir o grupo pela descrição; não confiar no NCM.", "Escolher a marca da lista (nome padronizado); marca nova só quando não existir.", "Preencher condição e características (material, comprimento).", "Marcar \"Revisei: liberar peça\"."], "entrega": "Peças revisadas e liberadas", "impacto": "Grupo errado distorce margem e estoque por grupo; marca duplicada quebra filtros e campanhas de itens semelhantes.", "regras": "Todo produto tem tipo de grade. Peça sem tamanho usa \"Acessório · tamanho único\".", "situacao": "uso"}, {"codigo": "E06", "ordem": 6, "fase": 2, "area": "compras", "titulo": "Ratear frete e despesas no custo", "responsavel": "comprador", "apoio": ["financeiro"], "tela": "Entrada de mercadoria › Rateio e financeiro", "entrada": "Peças liberadas e comprovantes de frete e despesas", "procedimento": ["Escolher o regime tributário da nota.", "Lançar rubricas extras (frete pago à transportadora, CT-e) e marcar as que geram financeiro.", "Conferir a diferença da nota: precisa ficar em R$ 0,00."], "entrega": "Custo unitário de cada peça fechado com a nota", "impacto": "Custo errado leva a margem errada em todas as vendas daquela peça. Mudar rateio, rubrica ou regime tira a liberação das peças afetadas.", "regras": "Diferença diferente de R$ 0,00 bloqueia a confirmação.", "situacao": "uso"}, {"codigo": "E07", "ordem": 7, "fase": 2, "area": "cadastro", "titulo": "Definir o preço de venda pela margem", "responsavel": "comprador", "apoio": ["gestor"], "tela": "Peças (custo, preço, margem)", "entrada": "Custo fechado", "procedimento": ["Conferir o preço sugerido pela margem mínima configurada.", "Ajustar por marca e condição.", "Considerar taxa do meio de pagamento, comissão e frete grátis de VIP."], "entrega": "Preço gravado na peça", "impacto": "Preço abaixo da margem mínima corrói o resultado da live sem ninguém perceber até o fechamento.", "regras": "Um preço só em todos os canais: preço por canal gera conflito na fila.", "situacao": "uso"}, {"codigo": "E08", "ordem": 8, "fase": 2, "area": "fin", "titulo": "Conferir o financeiro da nota (a pagar)", "responsavel": "financeiro", "apoio": ["comprador"], "tela": "Entrada de mercadoria › Financeiro", "entrada": "Parcelas do XML ou condição negociada", "procedimento": ["Conferir parcelas, vencimentos e valores; informar quando o XML não trouxer.", "Escolher natureza financeira e centro de resultado de cada parcela.", "Conferir as rubricas que geram título para a transportadora."], "entrega": "Parcelas conferidas, vinculadas à nota (número e chave)", "impacto": "Sem parcelas o fluxo de caixa não enxerga a dívida e o vencimento passa.", "regras": "O checklist da confirmação exige o financeiro conferido. Os títulos nativos de contas a pagar estão no plano do módulo financeiro.", "situacao": "impl"}, {"codigo": "E09", "ordem": 9, "fase": 2, "area": "estoque", "titulo": "Confirmar a entrada e dar estoque", "responsavel": "comprador", "apoio": ["conferente"], "tela": "Entrada de mercadoria › Confirmar", "entrada": "Checklist completo", "procedimento": ["Conferir o checklist: fornecedor, peças liberadas, diferença zero e financeiro conferido.", "Escolher o local de estoque.", "Confirmar."], "entrega": "Unidades físicas no estoque do CRM, cada uma com número curto", "impacto": "Sem confirmar, a peça não existe para venda. Nada é enviado ao Bling nesta etapa.", "regras": "Estorno só é possível se nenhum título da entrada tiver baixa.", "situacao": "uso"}, {"codigo": "E10", "ordem": 10, "fase": 2, "area": "estoque", "titulo": "Gerar e imprimir as etiquetas", "responsavel": "conferente", "apoio": ["cadastro"], "tela": "Preparar live › Etiquetas e impressão", "entrada": "Unidades criadas na entrada", "procedimento": ["Mandar imprimir as etiquetas da entrada (QR e número curto).", "Conferir modelo, impressora e agente de impressão.", "Etiquetar cada unidade conferindo peça, cor e tamanho.", "Em etiqueta danificada, reimprimir informando o motivo."], "entrega": "Cada unidade etiquetada", "impacto": "Etiqueta trocada faz a cliente comprar na live um número que é outra peça.", "regras": "Número de até 4 dígitos, reaproveitado quando a peça sai do estoque. Reimpressão fica registrada com data, hora e usuário.", "situacao": "uso"}, {"codigo": "E11", "ordem": 11, "fase": 2, "area": "estoque", "titulo": "Guardar no local certo", "responsavel": "conferente", "apoio": [], "tela": "Compras e estoque › Estoque; Cadastros › Locais", "entrada": "Peças etiquetadas", "procedimento": ["Guardar por local: estoque principal, loja física ou live.", "Conferir se o local está marcado como vendável.", "Mover a unidade no painel sempre que ela mudar de lugar."], "entrega": "Estoque com local correto", "impacto": "Local errado faz a vitrine mostrar o que não pode vender, ou esconder o que pode.", "regras": "A vitrine só mostra unidades em locais vendáveis.", "situacao": "uso"}, {"codigo": "E12", "ordem": 12, "fase": 3, "area": "mkt", "titulo": "Fotografar e montar a oferta", "responsavel": "marketing", "apoio": ["apresentadora"], "tela": "Central de vendas › Montar conteúdo (Montar oferta)", "entrada": "Peça disponível e etiquetada", "procedimento": ["Fotografar e gravar vídeo (até 90 s); ordenar mídias, marcar capa e rótulos.", "Escrever título, descrição e medidas.", "Aplicar o modelo de legenda de cada canal e conferir o contador de caracteres.", "Conferir a prévia de feed, story, WhatsApp e página."], "entrega": "Conteúdo em rascunho", "impacto": "Sem foto de capa a peça não é reconhecida na live nem na vitrine.", "regras": "HTML da página só com as tags permitidas; fora disso é recusado.", "situacao": "uso"}, {"codigo": "E13", "ordem": 13, "fase": 3, "area": "mkt", "titulo": "Aprovar e publicar nos canais", "responsavel": "marketing", "apoio": ["gestor", "apresentadora"], "tela": "Montar oferta › Prévia e kit", "entrada": "Conteúdo em rascunho", "procedimento": ["Aprovação por admin, gestor ou apresentadora.", "Conferir: foto, preço, tamanho, medidas, peça disponível e etiquetada.", "Baixar o kit (mídias numeradas), copiar a legenda e o link com origem do canal.", "No feed, terminar a legenda com \"Comente {código} que te enviamos o link\".", "Registrar o endereço do post publicado."], "entrega": "Publicação registrada por canal", "impacto": "Link sem origem perde a medição de qual canal vende. Editar de novo volta a rascunho sem mexer na página publicada.", "regras": "Aprovar exige ao menos uma foto.", "situacao": "uso"}, {"codigo": "E14", "ordem": 14, "fase": 3, "area": "mkt", "titulo": "Manter a vitrine pública", "responsavel": "marketing", "apoio": ["gestor"], "tela": "Preparar live › Preferências da vitrine", "entrada": "Ofertas aprovadas", "procedimento": ["Definir prazo da reserva (padrão 15 min), ordem das fotos, aviso \"Avise-me\" e tema.", "Conferir na vitrine se só aparecem peças vendáveis."], "entrega": "Vitrine com link único por peça", "impacto": "Prazo curto demais perde vendas; longo demais trava a peça enquanto a fila espera.", "regras": "Bloqueados recebem \"não disponível\" sem saber do bloqueio.", "situacao": "uso"}, {"codigo": "E15", "ordem": 15, "fase": 3, "area": "live", "titulo": "Agendar e preparar a live", "responsavel": "gestor", "apoio": ["apresentadora", "conferente", "marketing"], "tela": "Preparar live › Agenda", "entrada": "Ofertas publicadas e estoque", "procedimento": ["Criar o compromisso do tipo Live com responsável e horário.", "Separar as peças e movê-las para o local Live.", "Montar o roteiro com número curto, tamanho e preço.", "Divulgar o horário nos canais."], "entrega": "Arara da live pronta e agenda da equipe", "impacto": "Peça sem etiqueta ou fora do local Live não entra na fila.", "regras": "Não escrever telefone, CPF ou endereço no título do compromisso.", "situacao": "uso"}, {"codigo": "E16", "ordem": 16, "fase": 4, "area": "live", "titulo": "Apresentar as peças na live", "responsavel": "apresentadora", "apoio": ["suporte"], "tela": "Instagram ao vivo + Central de vendas", "entrada": "Roteiro e arara", "procedimento": ["Falar número curto, tamanho, condição e preço de cada peça.", "Orientar: \"comente o número da peça\".", "Acompanhar a fila de cada peça na Central de vendas."], "entrega": "Comentários de interesse", "impacto": "Número falado errado gera reserva da peça errada.", "regras": "O webhook de comentários da live está em piloto controlado.", "situacao": "impl"}, {"codigo": "E17", "ordem": 17, "fase": 4, "area": "live", "titulo": "Capturar o interesse e formar a fila", "responsavel": "suporte", "apoio": [], "tela": "Live e vendas › Central de vendas", "entrada": "Comentário ou mensagem com o número da peça", "procedimento": ["O interesse entra com o canal de origem (live, feed, story, WhatsApp, vitrine).", "A fila é única por peça, qualquer que seja o canal.", "Pessoas da lista de bloqueio são descartadas e a tentativa é contada.", "Limite de reservas e \"já participa\" valem pelo parceiro (todos os @ da mesma pessoa)."], "entrega": "Fila ordenada por peça", "impacto": "Atender fora da fila quebra a regra \"primeiro a se candidatar\" e gera reclamação pública.", "regras": "Motivo de saída é gravado desde o primeiro dia (demanda perdida).", "situacao": "impl"}, {"codigo": "E18", "ordem": 18, "fase": 4, "area": "live", "titulo": "Reservar e enviar o link de pagamento", "responsavel": "suporte", "apoio": [], "tela": "Central de vendas; Caixa de entrada (/link)", "entrada": "Primeira pessoa da fila", "procedimento": ["A primeira da fila ganha a reserva com prazo (padrão 15 min).", "Enviar o link único da reserva por DM (/link).", "VIP: acumula peças até o limite e paga no fim do dia ou da live.", "Acompanhar a contagem do prazo."], "entrega": "Reserva ativa e link enviado", "impacto": "Link atrasado consome o prazo da cliente. No Instagram só dá para responder até 24 h após a última mensagem dela.", "regras": "Limites de VIP (peças e valor) são definidos por cliente em Parceiros › Regras.", "situacao": "impl"}, {"codigo": "E19", "ordem": 19, "fase": 4, "area": "live", "titulo": "Atender na Caixa de entrada", "responsavel": "suporte", "apoio": ["gestor"], "tela": "Live e vendas › Caixa de entrada", "entrada": "Mensagens das clientes", "procedimento": ["Assumir a conversa (Minhas / Sem responsável).", "Responder com respostas prontas: /pix, /link, /prazo, /rastreio.", "Usar nota interna para recados à equipe.", "Resolver ou adiar; bloquear perfil de spam (admin ou gestor)."], "entrega": "Cliente atendida pelo mesmo canal", "impacto": "Duas pessoas na mesma conversa duplicam mensagens. No WhatsApp, cada número tem 1.000 respostas grátis por mês.", "regras": "Prévia trava o envio se faltar dado de uma variável.", "situacao": "uso"}, {"codigo": "E20", "ordem": 20, "fase": 4, "area": "live", "titulo": "Cliente informa a entrega e paga", "responsavel": "suporte", "apoio": ["financeiro"], "tela": "Link da reserva (página da vitrine no celular)", "entrada": "Link aberto pela cliente", "procedimento": ["CEP primeiro; endereço já usado em um toque.", "CPF de quem paga (pode ser outra pessoa; CPF sem cadastro pede o nome).", "Escolher Pix (copia e cola com prazo) ou cartão na página segura da Getnet.", "Sem gateway ligado, o link segue para o WhatsApp com a forma escolhida."], "entrega": "Cobrança gerada", "impacto": "Dados de entrega incompletos travam a NF-e e o envio.", "regras": "A loja nunca recebe nem guarda número de cartão. Funções da Getnet escritas, ainda não publicadas.", "situacao": "impl"}, {"codigo": "E21", "ordem": 21, "fase": 4, "area": "live", "titulo": "Tratar prazo vencido, desistência e próximo da fila", "responsavel": "suporte", "apoio": ["gestor"], "tela": "Central de vendas; Preparar live › Agenda (follow-up)", "entrada": "Reserva vencida ou cliente que desistiu", "procedimento": ["A reserva vence sozinha e a peça passa ao próximo da fila.", "Registrar o motivo de saída (não pagou, desistiu, trocou de peça).", "Criar follow-up na Agenda e registrar cada tentativa de contato.", "Quem ficou na fila é avisado quando a peça sai."], "entrega": "Histórico de cancelamentos do cliente e demanda perdida", "impacto": "Motivo não gravado é dado de demanda perdida que não se recupera depois.", "regras": "Encerrar follow-up sem resposta exige o mínimo de tentativas (padrão 3).", "situacao": "uso"}, {"codigo": "E22", "ordem": 22, "fase": 4, "area": "live", "titulo": "Confirmar o pagamento", "responsavel": "suporte", "apoio": ["financeiro"], "tela": "Central de vendas › Marcar pago; notificação Getnet", "entrada": "Pagamento aprovado ou Pix visto no extrato", "procedimento": ["Getnet aprovado: o registro é automático.", "Pix conferido no extrato ou pagamento na loja: \"Marcar pago\" com forma, frete e como foi conferido.", "A reserva vira paga: nasce o pedido no nome de quem pagou e a fila é avisada.", "O @ de quem reservou passa para os contatos do pagador (ex.: filha e mãe)."], "entrega": "Pedido pago", "impacto": "Marcar pago sem ver o dinheiro no extrato gera venda sem recebimento.", "regras": "Marcar pago: admin, gestor, suporte e financeiro. Fica registrado no log de ações.", "situacao": "impl"}, {"codigo": "E23", "ordem": 23, "fase": 5, "area": "exp", "titulo": "Montar o envio", "responsavel": "expedicao", "apoio": ["suporte"], "tela": "Clientes e pós-venda › Expedição › A montar", "entrada": "Pedidos pagos", "procedimento": ["Ver os pedidos pagos agrupados por cliente e endereço.", "Juntar peças pagas em momentos diferentes num envio só.", "Conferir o aviso de peças ainda reservadas da cliente antes de fechar."], "entrega": "Envio aguardando frete", "impacto": "Envios separados para a mesma cliente dobram o frete.", "regras": "Situações: aguardando frete → frete cobrado → pronta → enviada → entregue.", "situacao": "uso"}, {"codigo": "E24", "ordem": 24, "fase": 5, "area": "exp", "titulo": "Cobrar o frete", "responsavel": "expedicao", "apoio": ["suporte", "financeiro"], "tela": "Expedição › Em andamento", "entrada": "Envio montado", "procedimento": ["Definir o valor do frete, ou frete grátis para VIP.", "O frete vira cobrança própria enviada à cliente.", "Marcar frete pago quando confirmado."], "entrega": "Envio pronto", "impacto": "Postar sem frete pago é prejuízo direto.", "regras": "Frete calculado pelo CEP (Melhor Envio) é etapa futura.", "situacao": "uso"}, {"codigo": "E25", "ordem": 25, "fase": 5, "area": "estoque", "titulo": "Separar e conferir as peças do envio", "responsavel": "conferente", "apoio": ["expedicao"], "tela": "Expedição; Estoque (número curto e QR)", "entrada": "Envio pronto", "procedimento": ["Separar as unidades pelo número curto ou QR.", "Conferir peça, cor e tamanho contra o pedido.", "Conferir estado da peça e embalar."], "entrega": "Volume conferido e embalado", "impacto": "Peça trocada gera devolução, frete em dobro e cliente insatisfeita.", "regras": "A unidade sai do estoque e o número curto volta a ficar livre.", "situacao": "uso"}, {"codigo": "E26", "ordem": 26, "fase": 5, "area": "fat", "titulo": "Emitir a NF-e de venda no Bling", "responsavel": "faturista", "apoio": ["suporte"], "tela": "Cadastros › Parceiros (Pronto para NF-e); Bling; Configuração › Notas Bling", "entrada": "Pedido pago e parceiro com dados fiscais", "procedimento": ["Conferir no parceiro \"Pronto para NF-e\": CPF, endereço principal com IBGE.", "O pedido vai ao Bling só depois do pagamento, um por cliente e live.", "Gerar a NF-e do pedido e enviar à Sefaz.", "Conferir o NCM dos itens (nunca 0000.00.00) e anexar o DANFE ao envio."], "entrega": "NF-e autorizada e DANFE", "impacto": "Dois emissores (Bling automático e motor) geram nota duplicada. NCM zerado é risco fiscal.", "regras": "Um único emissor. Cancelamento de NF-e autorizada é manual no Bling.", "situacao": "impl"}, {"codigo": "E27", "ordem": 27, "fase": 5, "area": "exp", "titulo": "Postar e informar o rastreio", "responsavel": "expedicao", "apoio": ["suporte"], "tela": "Expedição › Enviar; Caixa de entrada (/rastreio)", "entrada": "Volume com NF-e", "procedimento": ["Postar na transportadora.", "Informar transportadora e código de rastreio no envio.", "Avisar a cliente com /rastreio.", "Se errou, \"Desfazer envio\" e corrigir."], "entrega": "Envio enviado com rastreio", "impacto": "Sem rastreio no painel o suporte não responde a cliente e a pergunta volta várias vezes.", "regras": "O rastreio não vem pela nota; é informado aqui.", "situacao": "uso"}, {"codigo": "E28", "ordem": 28, "fase": 6, "area": "live", "titulo": "Acompanhar a entrega e o pós-venda", "responsavel": "suporte", "apoio": ["expedicao"], "tela": "Agenda (pós-venda); Caixa de entrada; Parceiros", "entrada": "Envio enviado", "procedimento": ["Acompanhar até entregue.", "Criar compromisso de pós-venda e registrar a resposta da cliente.", "Encerrar só com resposta ou com o mínimo de tentativas."], "entrega": "Envio entregue e histórico de compras da cliente", "impacto": "Problema de entrega sem acompanhamento vira reclamação pública na live seguinte.", "regras": "Lembretes aparecem em qualquer tela do painel.", "situacao": "uso"}, {"codigo": "E29", "ordem": 29, "fase": 6, "area": "fat", "titulo": "Tratar cancelamento, troca e devolução", "responsavel": "suporte", "apoio": ["faturista", "conferente", "financeiro"], "tela": "Parceiros (histórico); Notas Bling; Estoque", "entrada": "Pedido de troca, devolução ou cancelamento", "procedimento": ["Registrar o motivo no histórico da cliente.", "Faturista emite ou recebe a nota de devolução (entrada) no Bling.", "Conferente reconfere a peça e devolve ao estoque com nova etiqueta, se preciso.", "Financeiro estorna ou devolve o valor, ou gera crédito de loja."], "entrega": "Histórico de cancelamentos e devoluções da cliente", "impacto": "Desistências repetidas pesam na decisão de VIP e na lista de bloqueio.", "regras": "Peça que volta não reabre a fila antiga; quem estava na fila pode ser avisada primeiro.", "situacao": "impl"}, {"codigo": "E30", "ordem": 30, "fase": 6, "area": "fin", "titulo": "Contas a receber e taxas", "responsavel": "financeiro", "apoio": [], "tela": "Financeiro › Contas a pagar e a receber (planejado); Painel de Gestão", "entrada": "Pagamentos confirmados", "procedimento": ["Título a receber nasce no pagamento confirmado, ligado ao pedido e à nota.", "Pix nasce baixado na conta da Getnet