ntrada": "Vendas, títulos e estoque do período", "procedimento": ["Mapear categorias do Bling às naturezas (De-Para) e revisar as não mapeadas.", "Ver vendas, cancelamentos, devoluções e venda líquida por canal.", "Ver fluxo de caixa e saldo por dia.", "Decidir as compras do próximo ciclo: volta à etapa 1."], "entrega": "Resultado do mês por canal e decisões de compra", "impacto": "Natureza ou centro de resultado errado distorce o DRE do canal.", "regras": "Valores em R$ são de administração, gestão e financeiro.", "situacao": "uso"}]}$semente$::jsonb);
  insert into crm.log_fluxo_revisao (empresa_id, versao, descricao, etapas, tipo, copia, criado_por)
  values (p_empresa, '1.0', 'Versão inicial: 33 etapas em 6 fases e 8 áreas, montadas a partir do manual do painel v0.11, dos pedidos de mudança até o 048 e do plano do módulo financeiro.',
          '{}', 'inicial', crm._fluxo_copia(p_empresa), null)
  on conflict (empresa_id, versao) do nothing;
end $$;

create or replace function api.fluxo_obter(p_empresa uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_nivel text; v_eu uuid := (select auth.uid());
begin
  perform crm._fluxo_exigir(p_empresa, 'ver');
  perform crm._fluxo_semear(p_empresa);
  v_nivel := api.nivel_tela(p_empresa, 'fluxo');
  return jsonb_build_object(
    'nivel', v_nivel,
    'versao', (select versao from crm.log_fluxo_revisao where empresa_id = p_empresa order by criado_em desc limit 1),
    'funcoes', coalesce((select jsonb_agg(jsonb_build_object('codigo', f.codigo, 'nome', f.nome, 'descricao', f.descricao) order by f.ordem, f.nome)
                           from crm.cad_fluxo_funcao f where f.empresa_id = p_empresa and f.ativa), '[]'::jsonb),
    'etapas', crm._fluxo_copia(p_empresa),
    'comentarios', coalesce((select jsonb_agg(jsonb_build_object(
        'id', c.id, 'etapa', c.etapa_codigo, 'tipo', c.tipo, 'texto', c.texto, 'criado_em', c.criado_em,
        'autor', coalesce(uc.nome, 'Equipe'), 'meu', c.criado_por is not distinct from v_eu, 'resolvido', c.resolvido,
        'resolvido_por', ur.nome, 'resolvido_em', c.resolvido_em) order by c.criado_em desc)
      from crm.mov_fluxo_comentario c
      left join crm.cad_usuario uc on uc.id = c.criado_por
      left join crm.cad_usuario ur on ur.id = c.resolvido_por
     where c.empresa_id = p_empresa), '[]'::jsonb),
    'revisoes', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'versao', r.versao, 'descricao', r.descricao, 'etapas', to_jsonb(r.etapas), 'tipo', r.tipo,
        'criado_em', r.criado_em, 'autor', coalesce(u.nome, case when r.criado_por is null then 'Implantação' else 'Equipe' end)) order by r.criado_em desc)
      from crm.log_fluxo_revisao r left join crm.cad_usuario u on u.id = r.criado_por
     where r.empresa_id = p_empresa), '[]'::jsonb));
end $$;

revoke all on function crm._fluxo_semear(uuid) from public, anon, authenticated;
revoke all on function api.fluxo_obter(uuid) from public, anon;
grant execute on function api.fluxo_obter(uuid) to authenticated;

select crm._fluxo_semear(id) from crm.cad_empresa;
